import os, re

# Load grids
d = os.environ['RLM_SESSION_DIR']
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

sr, sc = 0, 7  # Seed position
H, W = 11, 17

# Observed boundaries for upper part (y <= 6)
L_obs = [7,5,5,2,2,2,0]
R_obs = [7,9,9,12,12,12,16]

print("=== Trying ceiling-based formulas ===")

# Try: L(y) = max(0, sc - 2*ceil(y/3))
# For y=0: ceil(0)=0 → L = 7 - 0 = 7 ✓
# For y=1: ceil(0.33)=1 → L = 7 - 2 = 5 ✓  
# For y=2: ceil(0.67)=1 → L = 7 - 2 = 5 ✓
# For y=3: ceil(1)=1 → L = 7 - 2 = 5, but we want 2 ✗

# Hmm, that's close but not quite right

# Maybe the threshold changes? What about different formulas for different segments?

# Try: L(y) for y in [0,6]
# y=0: special case (just seed)
# y=1,2: L = sc - 2
# y=3,4,5: L = sc - 5
# y=6: L = 0

def compute_L_scoped(y):
    if y == 0:
        return sc
    elif y <= 2:
        return max(0, sc - 2)
    elif y <= 5:
        return max(0, sc - 5)
    else:
        return max(0, sc - 7)

def compute_R_scoped(y):
    if y == 0:
        return sc
    elif y <= 2:
        return min(W-1, sc + 2)
    elif y <= 5:
        return min(W-1, sc + 5)
    else:
        return min(W-1, sc + 9)  # From y=3 to y=6: increase by 9

print("\nScoped formula test:")
for y in range(7):
    L = compute_L_scoped(y)
    R = compute_R_scoped(y)
    match = f"L={L}✓" if L == L_obs[y] else f"L={L}✗"
    match += f", R={R}{'✓' if R==R_obs[y] else '✗'}"
    print(f"y={y}: {match}")

# Now let me verify against actual output
print("\n=== Verifying against demo output ===")
out = G['Demo pair 1 output']

def solve_demographic(grid):
    H_grid, W_grid = len(grid), len(grid[0])
    result = [[grid[i][j] for j in range(W_grid)] for i in range(H_grid)]

    sr, sc = None, None
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v == 2:
                sr, sc = i, j

    for y in range(H_grid):
        # Lower part (y > 6)
        if y > 6:
            L, R = 5, 5
        elif y == 6:
            L, R = 0, W_grid - 1
        else:
            # Upper part (y <= 6)
            if y == 0:
                L, R = sc, sc
            elif y <= 2:
                L, R = max(0, sc - 2), min(W_grid-1, sc + 2)
            else:  # y >= 3 and y <= 5
                L, R = max(0, sc - 5), min(W_grid-1, sc + 5)

        for x in range(L, R + 1):
            result[y][x] = 2

    return result

sol = solve_demographic(G['Demo pair 1 input'])
matches = True
for y in range(H):
    row_out = out[y]
    row_sol = sol[y]
    if row_out != row_sol:
