import os, re

# Load grids  
d = os.environ['RLM_SESSION_DIR']
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

out_demo = G['Demo pair 1 output']
in_demo = G['Demo pair 1 input']
test_in = G['Test input']

def solve_pattern(grid):
    """Based on mod 6 pattern"""
    H_grid, W_grid = len(grid), len(grid[0])

    sr, sc = None, None
    for i, row in enumerate(grid):
        if 2 in row:
            sr, sc = i, row.index(2)

    result = [[grid[i][j] for j in range(W_grid)] for i in range(H_grid)]

    # Pattern from demo: period = 6
    L_vals = {0: 7,  1: 5,  2: 5,  3: 2,  4: 2,  5: 2}
    R_vals = {0: 7,  1: 9,  2: 9,  3: 12,  4: 12,  5: 12}

    c_lower = 5

    for y in range(H_grid):
        dy = abs(y - sr)

        if dy == 0:
            continue  # Just seed

        elif dy <= 6:  # Upper part
            if dy % 6 in [1, 3]:  # Continuous rows
                L, R = L_vals.get(dy, sc), R_vals.get(dy, W_grid-1)
                for x in range(L, R+1):
                    if grid[y][x] == 0:
                        result[y][x] = 2
            else:  # Sparse rows (dy % 6 in [0,2,4,5])
                L, R = L_vals.get(dy, sc), R_vals.get(dy, W_grid-1)
                # Only endpoints
                if grid[y][L] == 0:
                    result[y][L] = 2
                if grid[y][R] == 0:
                    result[y][R] = 2
        else:  # Lower part
            result[y][c_lower] = 2

    return result

sol = solve_pattern(in_demo)
print("=== Solving demo ===")
matches_all = True
for y in range(len(out_demo)):
    matches = out_demo[y] == sol[y]
    if not matches:
        print(f"MISMATCH y={y}:")
        print(f"  Out: {' '.join(str(c) for c in out_demo[y])}")
