lines = test_input_str.strip().split('\n')
test_grid = [[int(c) for c in line.split()] for line in lines]
H, W = len(test_grid), len(test_grid[0])

def solve_always_fill(grid):
    """Always set target positions to 2, regardless of original value"""
    H_grid, W_grid = len(grid), len(grid[0])
    sr, sc = next((i, row.index(2)) for i, row in enumerate(grid) if 2 in row)

    result = [[grid[i][j] for j in range(W_grid)] for i in range(H_grid)]
    offset_small, offset_large = 2, 5
    c_lower = (W_grid - 2) // 3

    for y in range(H_grid):
        dy = abs(y - sr)

        if dy == 0:
            continue

        elif dy < 6:
            if dy == 1 or dy == 3:
                L, R = max(0, sc - (2 if dy==1 else 5)), min(W_grid-1, sc + (2 if dy==1 else 5))
                for x in range(L, R+1):
                    result[y][x] = 2
            else:
                L, R = max(0, sc - (2 if dy<=2 else 5)), min(W_grid-1, sc + (2 if dy<=2 else 5))
                result[y][L] = 2
                result[y][R] = 2
        elif dy == 6:
            for x in range(W_grid):
                result[y][x] = 2
        else:
            result[y][c_lower] = 2

    return result

def solve_only_zeros(grid):
    """Only convert cells that are currently 0"""
    H_grid, W_grid = len(grid), len(grid[0])
    sr, sc = next((i, row.index(2)) for i, row in enumerate(grid) if 2 in row)

    result = [[grid[i][j] for j in range(W_grid)] for i in range(H_grid)]
    offset_small, offset_large = 2, 5
    c_lower = (W_grid - 2) // 3

    for y in range(H_grid):
        dy = abs(y - sr)

        if dy == 0:
            continue

        elif dy < 6:
            if dy == 1 or dy == 3:
                L, R = max(0, sc - (2 if dy==1 else 5)), min(W_grid-1, sc + (2 if dy==1 else 5))
                for x in range(L, R+1):
                    if grid[y][x] == 0:
                        result[y][x] = 2
            else:
                L, R = max(0, sc - (2 if dy<=2 else 5)), min(W_grid-1, sc + (2 if dy<=2 else 5))
                if grid[y][L] == 0:
                    result[y][L] = 2
                if grid[y][R] == 0:
                    result[y][R] = 2
        elif dy == 6:
            for x in range(W_grid):
                if grid[y][x] == 0:
                    result[y][x] = 2
        else:
            if grid[y][c_lower] == 0:
                result[y][c_lower] = 2

    return result

