for row in sol_always:
    print(' '.join(str(c) for c in row))

print("\n=== SOLUTION ONLY ZEROS ===")
for row in sol_zeros:
    print(' '.join(str(c) for c in row))

# Find differences
diffs = []
for y in range(H):
    row_always = [str(c) for c in sol_always[y]]
    row_zeros = [str(c) for c in sol_zeros[y]]
    for x in range(W):
        if row_always[x] != row_zeros[x]:
            diffs.append((y, x, int(row_always[x]), int(row_zeros[x])))

print(f"\n=== Diffs between two approaches ({len(diffs)} cells differ) ===")
